/// C# `enum MATERIAL : i32`.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum MATERIAL {
    NONE_ = 0x0,
    WEAPON = 0x1,
    FLESH = 0x2,
    METAL = 0x3,
    GLASS = 0x4,
    CLOTH = 0x5,
    WOOD = 0x6,
    EARTH = 0x7,
    WATER = 0x8,
    ICE = 0x9,
    GRAVEL = 0xa,
    STONE = 0xb,
    FOOT_LARGE = 0xc,
    FOOT_BARE = 0xd,
    FOOT_SHOE = 0xe,
    FOOT_METAL = 0xf,
    FOOT_STEALTH = 0x10,
}

impl MATERIAL {
    /// Decode from the on-disk value. `None` for anything undefined —
    /// a C-style cast would produce a value outside the enum, which is UB.
    pub fn fromRaw(v: i32) -> Option<Self> {
        Some(match v {
            0x0 => Self::NONE_,
            0x1 => Self::WEAPON,
            0x2 => Self::FLESH,
            0x3 => Self::METAL,
            0x4 => Self::GLASS,
            0x5 => Self::CLOTH,
            0x6 => Self::WOOD,
            0x7 => Self::EARTH,
            0x8 => Self::WATER,
            0x9 => Self::ICE,
            0xa => Self::GRAVEL,
            0xb => Self::STONE,
            0xc => Self::FOOT_LARGE,
            0xd => Self::FOOT_BARE,
            0xe => Self::FOOT_SHOE,
            0xf => Self::FOOT_METAL,
            0x10 => Self::FOOT_STEALTH,
            _ => return None,
        })
    }
    /// The on-disk value.
    pub fn toRaw(self) -> i32 {
        self as i32
    }
}

