/// C# `default(E_BONE)`: its quaternions are all zeros, not glam's identity.
impl Default for E_BONE {
    fn default() -> Self {
        let q = Quat::from_xyzw(0.0, 0.0, 0.0, 0.0);
        Self {
            NumIdxVertices: 0, IdxVertices: None,
            OriginalGroup: None,
            Father: 0,
            QuatAnim: q, TransAnim: Vec3::ZERO, ScaleAnim: Vec3::ZERO,
            QuatLast: q, TransLast: Vec3::ZERO, ScaleLast: Vec3::ZERO,
            QuatInit: q, TransInit: Vec3::ZERO, ScaleInit: Vec3::ZERO,
            TransInitGlobal: Vec3::ZERO,
        }
    }
}

impl E_BONE {
    pub fn addIdxToBone(&mut self, idx: i32) { let v = self.IdxVertices.get_or_insert_with(Vec::new); v.resize(self.NumIdxVertices as usize + 1, 0); v[self.NumIdxVertices as usize] = idx; self.NumIdxVertices += 1; }
}

