impl E_3DOBJ {
    pub(crate) fn centerObjectCoordinates(&mut self) {
        let Vertexs = self.Vertexs.as_mut().unwrap();
        let offset = Vertexs[self.Origin as usize].V;
        if offset.x == 0.0 && offset.y == 0.0 && offset.z == 0.0 { return; }
        Log::info(&format!("NOT CENTERED {}\n", self.File));
        for i in 0..self.NumVertex as usize { Vertexs[i].V -= offset; Vertexs[i].Vert.S -= offset; }
        self.Point0 -= offset;
    }

    pub(crate) fn createCedricData(&mut self) {
        fn getFather(Groups: &[E_GROUPLIST], origin: i32, startGroup: i32) -> i32 {
            for i in (0..=startGroup).rev() {
                for j in 0..Groups[i as usize].NumIndex as usize {
                    if Groups[i as usize].Indexes.as_ref().unwrap()[j] == origin { return i; }
                }
            }
            -1
        }

        let mut temp: Vec<bool>;
        if self.NumGroups <= 0 {
            let Bones = self.Bones.insert(vec![E_BONE::default(); 1]);
            let s = &mut Bones[0];
            for i in 0..self.NumVertex { s.addIdxToBone(i); }
            s.TransInitGlobal = s.TransInit;
            s.OriginalGroup = None;
            s.Father = -1;
        }
        else {
            let (Groups, Vertexs) = (self.Groups.as_ref().unwrap(), self.Vertexs.as_ref().unwrap());
            let Bones = self.Bones.insert(vec![E_BONE::default(); self.NumGroups as usize]);
            temp = vec![false; self.NumVertex as usize];
            for i in (0..self.NumGroups as usize).rev() {
                let s = &mut Bones[i];
                let vorigin = Vertexs[Groups[i].Origin as usize];
                for j in 0..Groups[i].NumIndex as usize {
                    let idx = Groups[i].Indexes.as_ref().unwrap()[j];
                    if !temp[idx as usize] { temp[idx as usize] = true; s.addIdxToBone(idx); }
                }
                s.TransInit = vorigin.V;
                s.TransInitGlobal = s.TransInit;
                s.OriginalGroup = Some(Groups[i].clone());
                s.Father = getFather(Groups, Groups[i].Origin, i as i32 - 1);
            }

            // Try to correct lonely vertex
            for i in 0..self.NumVertex {
                let mut ok = false;
                for j in 0..self.NumGroups as usize {
                    for k in 0..Groups[j].NumIndex as usize {
                        if Groups[j].Indexes.as_ref().unwrap()[k] == i { ok = true; break; }
                    }
                    if ok { break; }
                }
                if !ok { Bones[0].addIdxToBone(i); }
            }

            for i in (0..self.NumGroups as usize).rev() {
                let Father = Bones[i].Father;
                if Father >= 0 { let f = Bones[Father as usize].TransInit; Bones[i].TransInit -= f; }
                Bones[i].TransInitGlobal = Bones[i].TransInit;
            }
        }

        // Build proper mesh
        let Bones = self.Bones.as_mut().unwrap();
        for i in 0..Bones.len() {
            let Father = Bones[i].Father;
            if Father >= 0 {
                let (fQuatAnim, fTransAnim) = (Bones[Father as usize].QuatAnim, Bones[Father as usize].TransAnim);
                let s = &mut Bones[i];
                s.QuatAnim = fQuatAnim * s.QuatInit; // Rotation
                Self::transformVertexQuat(&fQuatAnim, &s.TransInit, &mut s.TransAnim); // Translation
                s.TransAnim = fTransAnim + s.TransAnim;
                s.ScaleAnim = Vec3::new(1.0, 1.0, 1.0); // Scale
            }
            else {
                let s = &mut Bones[i];
                s.QuatAnim = s.QuatInit; // Rotation
                s.TransAnim = s.TransInit; // Translation
                s.ScaleAnim = Vec3::new(1.0, 1.0, 1.0); // Scale
            }
        }
        let VertexLocal = self.VertexLocal.insert(vec![Vec4::ZERO; self.NumVertex as usize]);
        let Vertexs = self.Vertexs.as_ref().unwrap();
        for i in 0..Bones.len() {
            let s = &Bones[i];
            let vec = s.TransAnim;
            for v in 0..s.NumIdxVertices as usize {
                let idx = s.IdxVertices.as_ref().unwrap()[v] as usize;
                let mut t = Vertexs[idx].V - vec;
                let t0 = t;
                Self::transformInverseVertexQuat(&s.QuatAnim, &t0, &mut t);
                VertexLocal[idx] = Vec4::new(t.x, t.y, t.z, 0.0);
            }
        }
    }

    pub(crate) fn precomputeFastAccess(&mut self) {
        let getSelection = |selName: &str| -> i16 {
            for i in 0..self.NumSelections as usize {
                if self.Selections.as_ref().unwrap()[i].Name.eq_ignore_ascii_case(selName) { return i as i16; }
            }
            -1
        };
        let getGroup = |groupName: &str| -> i16 {
            for i in 0..self.NumGroups as usize {
                if self.Groups.as_ref().unwrap()[i].Name.eq_ignore_ascii_case(groupName) { return i as i16; }
            }
            -1
        };
        let getActionPointIdx = |text: &str| -> i16 {
            for i in 0..self.NumAction as usize {
                if self.Actions.as_ref().unwrap()[i].Name.eq_ignore_ascii_case(text) { return self.Actions.as_ref().unwrap()[i].Idx as i16; }
            }
            -1
        };
        let (mouthGroup, headGroup): (i16, i16);
        let FastAccess = E_FASTACCESS {
            VRight: getActionPointIdx("V_RIGHT"),
            URight: getActionPointIdx("U_RIGHT"),
            ViewAttach: getActionPointIdx("View_attach"),
            PrimaryAttach: getActionPointIdx("PRIMARY_ATTACH"),
            LeftAttach: getActionPointIdx("LEFT_ATTACH"),
            WeaponAttach: getActionPointIdx("WEAPON_ATTACH"),
            SecondaryAttach: getActionPointIdx("SECONDARY_ATTACH"),
            JawGroup: getGroup("jaw"),
            MouthGroup: { mouthGroup = getGroup("mouth all"); mouthGroup },
            MouthGroupOrigin: (if mouthGroup == -1 { -1 } else { self.Groups.as_ref().unwrap()[mouthGroup as usize].Origin }) as i16,
            HeadGroup: { headGroup = getGroup("head"); headGroup },
            HeadGroupOrigin: (if headGroup == -1 { -1 } else { self.Groups.as_ref().unwrap()[headGroup as usize].Origin }) as i16,
            Fire: getActionPointIdx("FIRE"),
            CarryAttach: getActionPointIdx("CARRY_ATTACH"),
            SelHead: getSelection("head"),
            SelChest: getSelection("chest"),
            SelLeggings: getSelection("leggings"),
            ..Default::default()
        };
        self.FastAccess = FastAccess;
    }

    fn transformVertexQuat(q: &Quat, s: &Vec3, t: &mut Vec3) {
        let (rx, ry, rz, rw) = (s.x * q.w - s.y * q.z + s.z * q.y, s.y * q.w - s.z * q.x + s.x * q.z, s.z * q.w - s.x * q.y + s.y * q.x, s.x * q.x + s.y * q.y + s.z * q.z);
        t.x = q.w * rx + q.x * rw + q.y * rz - q.z * ry; t.y = q.w * ry + q.y * rw + q.z * rx - q.x * rz; t.z = q.w * rz + q.z * rw + q.x * ry - q.y * rx;
    }

    fn transformInverseVertexQuat(q: &Quat, s: &Vec3, t: &mut Vec3) {
        let invNorm = 1.0 / q.length_squared(); // C# Quaternion.Inverse
        let p = Quat::from_xyzw(-q.x * invNorm, -q.y * invNorm, -q.z * invNorm, q.w * invNorm);
        let (x, y, z) = (s.x, s.y, s.z);
        let (qx, qy, qz, qw) = (p.x, p.y, p.z, p.w);
        let (rx, ry, rz, rw) = (x * qw - y * qz + z * qy, y * qw - z * qx + x * qz, z * qw - x * qy + y * qx, x * qx + y * qy + z * qz);
        t.x = qw * rx + qx * rw + qy * rz - qz * ry; t.y = qw * ry + qy * rw + qz * rx - qx * rz; t.z = qw * rz + qz * rw + qx * ry - qy * rx;
    }
}

