#[cfg(test)]
mod tests {
    use super::*;
    use std::mem::size_of;

    #[test]
    fn structSizesMatchPatterns() {
        assert_eq!(size_of::<TLVERTEX>(), TLVERTEX::Struct.1);
        assert_eq!(size_of::<E_CYLINDER>(), E_CYLINDER::Struct.1);
        assert_eq!(size_of::<E_SPHERE>(), E_SPHERE::Struct.1);
        assert_eq!(size_of::<E_SPRINGS>(), E_SPRINGS::Struct.1);
        assert_eq!(size_of::<CLOTHESVERTEX>(), CLOTHESVERTEX::Struct.1);
        assert_eq!(size_of::<COLLISION_SPHERE>(), COLLISION_SPHERE::Struct.1);
        assert_eq!(size_of::<SAVE_EPOLY>(), SAVE_EPOLY::Struct.1);
        assert_eq!(size_of::<E_SAVE_PORTALS>(), E_SAVE_PORTALS::Struct.1);
        assert_eq!(size_of::<EP_DATA>(), EP_DATA::Struct.1);
        assert_eq!(size_of::<E_SAVE_ROOM_DATA>(), E_SAVE_ROOM_DATA::Struct.1);
    }
}
